"""Editor navigation is private; every exit restores the player's frozen view."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);out=p.parse_args().output.resolve();out.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parents[1];checks=[]
def view(page):return page.evaluate('''()=>{const t=window.__SKY_STUDIO_TEST__,s=t.state;return {position:s.position,begin:t.rollFrame().begin,window:s.windowSec,clock:document.getElementById('timeClock').textContent,seek:document.getElementById('seekSlider').value}}''')
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True)
 for choice in ['saveDirect','saveAsNew','discardChanges']:
  page=b.new_page(viewport={'width':1366,'height':900});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto((root/'SkyMusicStudio_Standalone.html').as_uri());page.locator('.card-play').first.click();page.locator('#rollWindow').select_option('8');page.locator('#seekSlider').evaluate("e=>{e.value=2700;e.dispatchEvent(new Event('input'))}");page.locator('#rollSeekSlider').evaluate("e=>{e.value=63000;e.dispatchEvent(new Event('input'))}");player=view(page)
  page.locator('#scoreEditorBtn').click();page.locator('#consoleFineTab').click();assert view(page)['position']==0;page.locator('#eventDuration').fill('400');page.locator('#eventApply').click();page.locator('#rollWindow').select_option('20');page.locator('#rollSeekSlider').evaluate("e=>{e.value=111000;e.dispatchEvent(new Event('input'))}")
  g=page.evaluate('''()=>{const t=window.__SKY_STUDIO_TEST__,r=document.getElementById('rollCanvas').getBoundingClientRect(),f=t.rollFrame();return {...f,...t.rollPlotGeometry(r,f),x:r.x,y:r.y}}''');page.mouse.click(g['x']+g['left']+.35*g['plotW'],g['y']+g['top']-3);page.locator('#consolePlay').click();page.wait_for_function('window.__SKY_STUDIO_TEST__.state.isPlaying');page.wait_for_timeout(120);page.locator('#consolePlay').click();editor=view(page);assert editor['position']!=player['position'];assert editor['clock']==player['clock'] and editor['seek']==player['seek']
  page.locator('#consoleClose').click();page.locator('#'+choice).click();restored=view(page);assert restored==player,(choice,player,restored);assert page.locator('#beatGrid .beat').count()==32
  assert page.evaluate('window.__SKY_STUDIO_TEST__.state.project.score.events[0].durationMs')==(400 if choice!='discardChanges' else 180)
  page.locator('#scoreEditorBtn').click();cached=view(page);assert cached['position']==editor['position'] and cached['begin']==editor['begin'] and cached['window']==editor['window'];page.locator('#consoleGenerateTab').click();page.locator('#pageNext').click();assert view(page)['clock']==player['clock'] and view(page)['seek']==player['seek'];lastEditor=view(page);page.locator('#consoleClose').click();page.locator('#discardChanges').click();assert view(page)==player
  page.locator('#seekSlider').evaluate("e=>{e.value=21000;e.dispatchEvent(new Event('input'))}");page.locator('#scoreEditorBtn').click();assert view(page)['position']==lastEditor['position'];assert view(page)['clock']=='00:21.000';page.locator('#consoleClose').click();page.locator('#discardChanges').click();assert view(page)['position']==21000;assert not errors,errors;checks.append({'choice':choice,'restoredPlayer':True,'editorRemembersOwnView':True,'frozenPlayerControls':True,'savedScoreIndependent':True});page.close()
 b.close()
(out/'results.json').write_text(json.dumps({'passed':True,'checks':checks},indent=2),'utf-8');print('PASS independent player/editor positions, custom page origins and window lengths, frozen player display, per-song editor memory and all three exits')
